import * as THREE from '../vendor/three.module.js';
export function updateFaultBottom(v){if(v.sim.fault?.stage19&&!v.bioBottom){const g=new THREE.Group();g.userData.diagnosticId='organ:bottom';const geo=new THREE.PlaneGeometry(134,92,45,32);geo.rotateX(-Math.PI/2);geo.translate(67,0,46);const p=geo.attributes.position;for(let i=0;i<p.count;i++){const x=p.getX(i),z=p.getZ(i);p.setY(i,-13.08+.055*Math.sin(x*.6)*Math.cos(z*.5)+.025*Math.sin(x+z));}geo.computeVertexNormals();g.add(new THREE.Mesh(geo,new THREE.MeshStandardMaterial({color:0x752b38,roughness:.8,side:THREE.DoubleSide})));v.scene.add(g);v.bioBottom=g;}if(v.bioBottom)v.bioBottom.visible=!!v.sim.fault?.stage19;}
